const datasets=new DatasetWorkspace();let activeDataset='';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let lang=localStorage.getItem('datalens-language')||'zh', view='data', rows=penguins(), original=structuredClone(rows), cols=E.columns(rows), dataset='penguins.csv', isSample=true, history=[], undo=[], page=0, query='', sort=null, visible=[...cols], chartType='scatter', chartX='flipper_length_mm', chartY='body_mass_g', chartAgg='mean', analysisResult=null;
const t=(zh,en)=>lang==='zh'?zh:en, esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={species:['物种','Species'],island:['岛屿','Island'],bill_length_mm:['喙长 (mm)','Bill length (mm)'],bill_depth_mm:['喙深 (mm)','Bill depth (mm)'],flipper_length_mm:['鳍肢长 (mm)','Flipper length (mm)'],body_mass_g:['体重 (g)','Body mass (g)'],sex:['性别','Sex'],year:['观测年份','Year'],order_id:['订单编号','Order ID'],date:['日期','Date'],region:['地区','Region'],category:['品类','Category'],channel:['渠道','Channel'],revenue:['销售额','Revenue'],profit:['利润','Profit'],quantity:['数量','Quantity'],customer_rating:['客户评分','Rating']};
const values={Adelie:['阿德利企鹅','Adelie'],Gentoo:['巴布亚企鹅','Gentoo'],Chinstrap:['帽带企鹅','Chinstrap'],male:['雄性','Male'],female:['雌性','Female'],East:['华东','East'],South:['华南','South'],North:['华北','North'],West:['西部','West'],Technology:['科技数码','Technology'],Furniture:['家居生活','Furniture'],'Office supplies':['办公用品','Office supplies'],Online:['线上','Online'],Retail:['门店','Retail']};
const label=k=>isSample&&Object.hasOwn(names,k)?t(...names[k]):k, val=v=>E.missing(v)?t('缺失','Missing'):isSample&&Object.hasOwn(values,v)?t(...values[v]):v;
const fmt=(v,d=0)=>v===null||v===undefined||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString(lang==='zh'?'zh-CN':'en-US',{maximumFractionDigits:d});
const shortLabel=value=>{const str=String(value??'');return str.length>26?str.slice(0,25)+'…':str;};
const short=v=>Math.abs(v)>=1e6?(v/1e6).toFixed(1)+'m':Math.abs(v)>=1e3?(v/1e3).toFixed(1)+'k':fmt(v,1);
const color=['#4f46e5','#0e7490','#b85a16','#9333ea','#087f5b','#c73565','#c54d28','#2563eb'];
const paths={logo:'M4 19v-7m8 7V4m8 15V8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',table:'M3 4h18v16H3zM3 9h18M3 14h18M9 4v16M15 4v16',clean:'m14 3 7 7M4 13l9-9 7 7-9 9H4zM8 9l7 7M3 21h18',analysis:'M4 20V10m6 10V4m6 16v-7m6 7H2',chart:'M3 3v18h18M6 16l5-6 4 3 6-8',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',download:'M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',shield:'m12 3 9 4v6c0 5-9 9-9 9S3 18 3 13V7zM8 12l3 3 5-6',help:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 18h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',file:'M14 2H4v20h16V8zM14 2v6h6M8 13h8M8 17h5',rows:'M4 5h16M4 12h16M4 19h16',columns:'M5 4v16M12 4v16M19 4v16',check:'m5 12 4 4L19 6',alert:'m12 3 10 18H2zM12 9v5M12 17h.01',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z',filter:'M3 4h18l-7 8v8l-4-2v-6z',undo:'M9 4 3 10l6 6M3 10h11a7 7 0 0 1 7 7',reset:'M3 3v6h6M3 9a9 9 0 1 1 0 7',close:'m6 6 12 12M6 18 18 6',menu:'M3 5h18M3 12h18M3 19h18',globe:'M2 12h20M12 2c6 6 6 14 0 20-6-6-6-14 0-20M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',book:'M12 5C9 2 5 2 2 3v17c4-1 7-1 10 2 3-3 6-3 10-2V3c-3-1-7-1-10 2v17',plus:'M12 4v16M4 12h16'};
const icon=(name,cls='')=>'<svg class="icon '+cls+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[name]||paths.grid)+'"/></svg>';
const btn=(act,text,ic='',cls='',extra='')=>'<button type="button" data-act="'+act+'" class="'+cls+'" '+extra+'>'+(ic?icon(ic):'')+text+'</button>';
const opt=(value,text,selected)=>'<option value="'+esc(value)+'" '+(String(value)===String(selected)?'selected':'')+'>'+esc(text)+'</option>';
const select=(id,options,selected)=>'<select id="'+id+'">'+options.map(o=>opt(o[0],o[1],selected)).join('')+'</select>';
const field=(text,control)=>'<label class="field">'+esc(text)+control+'</label>';
const colopts=(numeric=false)=>E.profile(rows,cols).filter(c=>!numeric||c.type==='number').map(c=>[c.key,label(c.key)]);
const aggopts=()=>[['sum',t('求和','Sum')],['mean',t('平均值','Mean')],['count',t('有效计数','Non-null count')],['min',t('最小值','Minimum')],['max',t('最大值','Maximum')],['median',t('中位数','Median')]];
// Charts and analysis always use the complete working dataset.
const current=()=>rows;
const tableRows=()=>{let r=rows;if(query)r=r.filter(x=>cols.some(k=>[x[k],...(isSample&&Object.hasOwn(values,x[k])?values[x[k]]:[])].map(v=>String(v??'')).join(' ').toLowerCase().includes(query.toLowerCase())));if(sort)r=E.sortRows(r,sort.key,sort.dir);return r;};
const navs=()=>[['data','table',t('数据','Data')],['clean','clean',t('处理','Prepare')],['analysis','analysis',t('分析','Analyze')],['charts','chart',t('图表','Charts')]];
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function empty(s){return '<div class="empty">'+icon('chart')+s+'</div>';}
function render(){
 document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=t('DataLens · 数据探索工作台','DataLens · Data exploration studio');
 const title=navs().find(n=>n[0]===view)?.[2]||t('使用指南','Getting started');
 $('#app').innerHTML='<aside class="sidebar"><a href="#" class="brand" data-act="data"><span class="brand-mark">'+icon('logo')+'</span>DataLens<span style="color:#7963e9">.</span></a><div class="side-caption">'+t('工作空间','Workspace')+'</div><nav>'+navs().map(n=>btn(n[0],n[2]+(n[0]==='history'&&history.length?'<span class="badge">'+history.length+'</span>':''),n[1],'nav-btn '+(view===n[0]?'active':''))).join('')+'</nav>'+datasetPicker()+'<div class="side-bottom"><div class="local-card"><div class="shield">'+icon('shield')+'</div><h3 style="font-size:12px">'+t('本地数据处理','Local data processing')+'</h3><p>'+t('所有分析在浏览器中完成，无需上传到服务器。','All analysis runs in your browser. No data is sent to a server.')+'</p></div>'+btn('help',t('使用指南与项目介绍','Guide & about'),'help','nav-btn '+(view==='help'?'active':''))+'<div class="workspace flex"><span class="avatar">DL</span><div><div style="font-size:11px">'+t('个人工作空间','Personal workspace')+'</div><div class="tiny muted">Data exploration studio</div></div></div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb">'+btn('menu','','menu','ghost mobile-menu','aria-label="'+t('打开菜单','Open menu')+'"')+'<span>'+t('工作空间','Workspace')+'</span><span>/</span><strong>'+title+'</strong></div><div class="top-actions">'+datasetSize()+''+btn('language',lang==='zh'?'EN / 中文':'中文 / EN','globe','lang')+btn('help','','help','ghost','aria-label="'+t('使用指南','Help')+'"')+'</div></header><main class="main">'+heading()+(view==='data'?dataView():view==='clean'?cleanView():view==='analysis'?analysisView():view==='charts'?chartsView():view==='history'?historyView():helpView())+'<footer class="footer"><span>DataLens Studio</span><span>'+t('可视化导论课程项目','Introduction to Visualization project')+' / 2026</span></footer></main></div>';
 if(view==='data')renderProfile();if(view==='clean'){renderPrepare();if(pending&&pending.kind!=='prepare')showPreview();}if(view==='charts')renderMainChart();if(view==='analysis')renderAnalysisResult();
}
function heading(){
 const titles={
  overview:[t('数据概览','Overview'),t('查看数据规模、质量、趋势和分布。','View dataset size, quality, trends and distributions.')],
  data:[t('数据','Data'),t('从分布中认识数据，查看字段质量与分布。','Understand your data through distributions. Inspect field quality and distributions.')],
  clean:[t('处理','Prepare'),t('先预览变化，再应用清洗、计算与多表合并。','Preview changes before cleaning, calculating or joining tables.')],
  analysis:[t('分析','Analyze'),t('描述统计、分组聚合、透视表和相关性分析。','Descriptive statistics, grouping, pivot tables and correlations.')],
  charts:[t('图表','Charts'),t('字段、分布与相关性。','Fields, distributions and correlations.')],
  history:[t('操作记录','Activity history'),t('查看数据变换记录和对应的 pandas 操作。','Review transformations and corresponding pandas operations.')],
  help:[t('使用指南','User guide'),t('功能说明、数据格式和计算口径。','Features, file formats and calculation methods.')]
 };
 const [h,p]=titles[view]||titles.help;
 return '<div class="heading spread"><div><h1>'+h+'</h1></div><div class="header-buttons">'+(view==='data'?btn('export',t('导出数据','Export data'),'download')+btn('import',t('添加数据集','Add dataset'),'plus','primary'):view==='clean'?btn('history',t('操作记录','History'),'clock')+btn('undo',t('撤销','Undo'),'undo','',undo.length?'':'disabled')+btn('reset',t('重置','Reset'),'reset','ghost'):view==='charts'?btn('inspectRecords',t('查看记录','View records'),'rows'):'' )+'</div></div>';
}
function metric(title,value,note,ic,index){return '<div class="metric"><div class="metric-title">'+icon(ic)+title+'</div><div class="metric-value mono">'+value+'</div><div class="metric-note">'+note+'</div><svg class="spark" viewBox="0 0 75 32" fill="none"><path d="'+['M1 26 10 21 20 23 30 13 40 17 50 8 60 12 74 3','M1 24h12v-8h13v5h13V9h13v5h13V3h9','M1 27 14 23 27 17 40 20 53 8 65 12 74 5','M1 24 13 25 26 19 38 21 50 14 62 16 74 9'][index]+'" stroke="'+color[index]+'" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg></div>';}
function tableCard(data,preview=false){let p=E.profile(rows,cols),showcols=visible.filter(c=>cols.includes(c)),list=preview?showcols.slice(0,7):showcols;let all=preview?rows:tableRows();if(!preview){const max=Math.max(0,Math.ceil(all.length/12)-1);page=Math.min(page,max);data=all.slice(page*12,page*12+12);}return '<section class="card"><div class="table-head spread"><div class="flex"><h2>'+t(preview?'数据预览':'数据工作表',preview?'Data preview':'Data explorer')+'</h2><span class="badge">'+(preview?t('前 5 行','First 5 rows'):fmt(all.length)+' '+t('行','rows'))+'</span></div><div class="table-controls">'+(preview?btn('data',t('查看全部数据','View all data'),'chevron','small ghost'):'<label class="search"><span class="sr-only">'+t('搜索数据','Search data')+'</span>'+icon('search')+'<input id="search" value="'+esc(query)+'" placeholder="'+t('仅搜索工作表…','Search worksheet only…')+'"></label>'+btn('columns',t('显示列','Columns'),'columns','small'))+'</div></div><div class="table-scroll"><table><thead><tr><th class="row-index">#</th>'+list.map(k=>'<th>'+btn('sort',esc(label(k))+' <span style="font-size:9px;opacity:.6">'+(p.find(c=>c.key===k)?.type==='number'?'#':p.find(c=>c.key===k)?.type==='date'?'◷':'Aa')+'</span>'+(sort?.key===k?(sort.dir==='asc'?' ↑':' ↓'):''),'','','data-key="'+esc(k)+'"')+'</th>').join('')+'</tr></thead><tbody>'+data.map((r,i)=>'<tr><td class="row-index">'+String((preview?0:page*12)+i+1).padStart(2,'0')+'</td>'+list.map(k=>'<td class="'+(E.numeric(r[k])?'mono':'')+'">'+(E.missing(r[k])?'<span class="cell-null">'+t('缺失','null')+'</span>':isSample&&k==='category'?'<span class="category-tag '+(r[k]==='Furniture'?'furniture':r[k]==='Office supplies'?'office':'')+'">'+esc(val(r[k]))+'</span>':esc(isSample&&k==='year'?r[k]:E.numeric(r[k])?fmt(r[k],2):val(r[k])))+'</td>').join('')+'</tr>').join('')+'</tbody></table>'+(data.length?'':tableEmpty())+'</div><div class="table-footer"><span>'+t('显示','Showing')+' '+(all.length?(preview?1:page*12+1):0)+'–'+(preview?Math.min(5,rows.length):Math.min((page+1)*12,all.length))+' / '+fmt(all.length)+' '+t('行','rows')+'</span>'+(preview?'<span>'+t('点击表头排序 · 缺失值高亮显示','Click a header to sort · Missing values highlighted')+'</span>':'<div class="flex">'+btn('prev','‹','','small',page===0?'disabled':'')+'<span>'+t('第','Page')+' '+(page+1)+' / '+Math.max(1,Math.ceil(all.length/12))+'</span>'+btn('next','›','','small',(page+1)*12>=all.length?'disabled':'')+'</div>')+'</div></section>';}
function svgChart(data,type='line',yLabel='',xLabel=''){if(!data.length||data.every(d=>d.value===null))return empty(t('当前字段没有可绘制的数据。','No plottable values in these fields.'));let W=700,H=285,L=58,R=22,T=18,B=50;let vals=data.map(d=>d.value).filter(E.numeric),lo=Math.min(0,...vals),hi=Math.max(0,...vals);if(lo===hi)hi=lo+1;let span=hi-lo;hi+=span*.12;if(lo<0)lo-=span*.08;let y=v=>T+(hi-v)/(hi-lo)*(H-T-B),step=(W-L-R)/data.length,x=i=>L+step*(i+.5);let s='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+esc(shortLabel(yLabel))+'"><rect width="100%" height="100%" fill="white"/>';for(let i=0;i<=4;i++){let v=lo+(hi-lo)*i/4,yy=y(v);s+='<line x1="'+L+'" y1="'+yy+'" x2="'+(W-R)+'" y2="'+yy+'" stroke="#e4e7f3" stroke-dasharray="3 4"/><text x="'+(L-12)+'" y="'+(yy+4)+'" text-anchor="end">'+short(v)+'</text>';}
 if(type==='line'){let segments=[],segment=[];data.forEach((v,i)=>{if(E.numeric(v.value))segment.push({v,i});else if(segment.length){segments.push(segment);segment=[];}});if(segment.length)segments.push(segment);let d=segments.map(seg=>seg.map(({v,i},j)=>(j?'L':'M')+x(i)+','+y(v.value)).join(' ')).join(' '),areaD=segments.map(seg=>seg.map(({v,i},j)=>(j?'L':'M')+x(i)+','+y(v.value)).join(' ')+' L'+x(seg.at(-1).i)+','+y(0)+' L'+x(seg[0].i)+','+y(0)+' Z').join(' ');s+='<defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#7562ec" stop-opacity=".22"/><stop offset="1" stop-color="#7562ec" stop-opacity=".01"/></linearGradient></defs><path d="'+areaD+'" fill="url(#area)"/><path d="'+d+'" fill="none" stroke="#4f46e5" stroke-width="2.6" stroke-linejoin="round"/>'+data.map((v,i)=>E.numeric(v.value)?'<circle class="point" cx="'+x(i)+'" cy="'+y(v.value??0)+'" r="4" fill="white" stroke="#4f46e5" stroke-width="2"><title>'+esc(val(v.key))+': '+fmt(v.value,2)+'</title></circle>':'').join('');}
 else s+=data.map((v,i)=>'<rect class="bar" x="'+(x(i)-step*.31)+'" y="'+y(Math.max(0,v.value??0))+'" width="'+step*.62+'" height="'+Math.abs(y(v.value??0)-y(0))+'" rx="4" fill="'+color[i%color.length]+'"><title>'+esc(val(v.key))+': '+fmt(v.value,2)+'</title></rect>').join('');
 s+=data.map((v,i)=>i%Math.max(1,Math.ceil(data.length/9))===0?'<text class="axis-label" x="'+x(i)+'" y="'+(H-27)+'" text-anchor="middle">'+esc(String(val(v.key)).length>13?String(val(v.key)).slice(0,12)+'…':val(v.key))+'</text>':'').join('');return s+'<text x="'+L+'" y="10">'+esc(shortLabel(yLabel))+'</text><text x="'+(W-R)+'" y="'+(H-7)+'" text-anchor="end">'+esc(shortLabel(xLabel))+'</text></svg>';}
function donut(data){data=data.filter(d=>E.numeric(d.value)&&d.value>0);if(!data.length)return empty(t('环形图需要正数值。','A donut chart requires positive values.'));let total=data.reduce((a,b)=>a+b.value,0),offset=0;let s='<div class="donut-wrap"><svg viewBox="0 0 180 180" role="img" aria-label="'+t('构成分布','Composition')+'">';for(let i=0;i<data.length;i++){let pct=data[i].value/total;let length=pct*439.823;s+='<circle class="slice" cx="90" cy="90" r="70" fill="none" stroke="'+color[i%color.length]+'" stroke-width="21" stroke-dasharray="'+Math.max(0,length-4)+' '+(439.823-Math.max(0,length-4))+'" stroke-dashoffset="'+(-offset)+'"><title>'+esc(val(data[i].key))+': '+fmt(data[i].value,2)+' ('+fmt(pct*100,1)+'%)</title></circle>';offset+=length;}s+='</svg><div class="donut-center"><strong>'+short(total)+'</strong><span>'+t('合计','Total')+'</span></div></div><div class="legend-list">';return s+data.map((d,i)=>'<div class="legend-item"><span><i class="legend-dot" style="background:'+color[i%color.length]+'"></i>'+esc(val(d.key))+'</span><b>'+fmt(d.value/total*100,1)+'% <span style="display:inline-block;width:55px;text-align:right;color:#78829a">'+short(d.value)+'</span></b></div>').join('')+'</div>';}
function toolCard(title,code,desc,content){return '<section class="card card-pad tool-card"><div class="spread"><h2>'+title+'</h2><span class="code-tag">'+code+'</span></div><p>'+desc+'</p>'+content+'</section>';}
function analysisView(){
 const numeric=colopts(true),spec=groupSpec||initialConfig(rows).groupSpec,categories=categoryFields(),colorKey=categories[0]?.[0]||'',relation=spec.relation||'scattermatrix',keys=C.numericFields(rows,cols,4);
 const describeTable='<details class="card stats-details"><summary>'+t('描述性统计','Descriptive statistics')+'</summary><div class="card-pad"><p class="card-sub">'+t('忽略缺失值 · 样本标准差 ddof = 1 · 分位数线性插值','Missing values excluded · Sample std (ddof = 1) · Linear quantiles')+'</p><div class="table-scroll"><table><thead><tr>'+[t('字段','Column'),t('有效计数','Count'),t('均值','Mean'),t('标准差','Std'),t('最小值','Min'),'25%',t('中位数','Median'),'75%',t('最大值','Max')].map(k=>'<th>'+k+'</th>').join('')+'</tr></thead><tbody>'+numeric.map(([c])=>{const s=E.describe(current().map(r=>r[c]));return '<tr><td>'+esc(label(c))+'</td>'+['count','mean','std','min','q1','median','q3','max'].map(k=>'<td class="mono">'+fmt(s[k],2)+'</td>').join('')+'</tr>';}).join('')+'</tbody></table></div></div></details>';
 return `<div class="stack"><section class="card card-pad"><div class="spread"><h2>${t('分组聚合与透视','Group & pivot')}</h2><span class="code-tag">groupby / pivot_table</span></div><div class="form-row">${field(t('行维度','Row dimension'),select('groupRow',colopts(),spec.r))}${field(t('列维度（可选）','Column dimension (optional)'),select('groupCol',[['',t('无，仅分组','None · Group only')],...colopts()],spec.c))}${field(t('指标字段','Metric'),select('groupVal',colopts(),spec.v))}${field(t('聚合方式','Aggregation'),select('groupAgg',aggopts(),spec.fn))}${btn('aggregate',t('生成分析','Run analysis'),'analysis','primary')}</div><div id="analysisResult" class="operation-result"></div></section>
 <section class="card card-pad relation-panel"><div class="card-head"><h2>${t('多字段关系','Relationships across fields')}</h2><div class="segmented">${btn('analysisRelation',t('散点矩阵','Scatter matrix'),'','small '+(relation==='scattermatrix'?'selected':''),'data-kind="scattermatrix"')}${btn('analysisRelation',t('相关热力图','Correlation heatmap'),'','small '+(relation==='heatmap'?'selected':''),'data-kind="heatmap"')}</div></div><div class="wide-viz">${keys.length>=2?(relation==='heatmap'?matrix():extras.scatterMatrix(current(),keys,colorKey)):categories.length>=2?extras.categoryHeatmap(current(),categories[0][0],categories[1][0]):empty(t('需要至少两个数值或类别字段。','Requires at least two numeric or category fields.'))}</div></section>${timePanel()}${describeTable}</div>`;
}

function renderAnalysisTable(){if(!analysisResult||!$('#analysisResult'))return;const {data,headers,title}=analysisResult;$('#analysisResult').innerHTML='<div class="spread" style="margin:18px 0 12px"><h3>'+esc(title)+'</h3>'+btn('exportAnalysis',t('导出结果 CSV','Export result CSV'),'download','small')+'</div><div class="table-scroll"><table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+data.slice(0,100).map(r=>'<tr>'+r.map(v=>'<td>'+esc(E.numeric(v)?fmt(v,2):val(v))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="card-sub">'+t('共 ','Total: ')+data.length+t(' 行，最多预览 100 行。导出包含全部结果。',' rows. Preview limited to 100 rows; export contains all results.')+'</p>';}
function historyView(){return '<div class="card"><div class="table-head spread"><div><h2>'+t('数据处理流水线','Transformation pipeline')+'</h2><p class="card-sub">'+t('每个数据集分别保留最近 20 步撤销和独立的操作记录。','Each dataset retains its own history and the last 20 undo steps.')+'</p></div>'+btn('exportHistory',t('导出操作记录','Export history'),'download','small')+'</div><div class="history-row"><span class="step-number">0</span><div class="body"><h3>'+t('载入数据','Load dataset')+'</h3><p>'+esc(dataset)+' · '+original.length+' '+t('行','rows')+'</p><code>df = pd.read_'+(dataset.endsWith('.json')?'json':/\.xlsx(?:$| \/)/i.test(dataset)?'excel':'csv')+'('+esc(JSON.stringify(dataset))+')</code></div><span class="badge">'+t('初始状态','Initial state')+'</span></div>'+history.map((h,i)=>'<div class="history-row"><span class="step-number">'+(i+1)+'</span><div class="body"><h3>'+esc(t(h.zh,h.en))+'</h3><p>'+h.before+' → '+h.after+' '+t('行','rows')+' · '+new Date(h.time).toLocaleTimeString(lang==='zh'?'zh-CN':'en-US')+'</p><code>'+esc(h.code)+'</code></div><span class="badge">'+t('已完成','Completed')+'</span></div>').join('')+(history.length?'':'<div class="empty">'+t('尚未进行数据变换。试试缺失值填充或创建计算字段。','No transformations yet. Try filling missing values or creating a calculated field.')+'</div>')+'</div><div class="insight">'+icon('help')+t('pandas 片段用于解释操作思路，并非完整可执行脚本；计算实际由本地 JavaScript 引擎完成。','The pandas snippets illustrate operations, not a complete executable script. Calculations run in a local JavaScript engine.')+'</div>';}
function modal(title,body,footer=''){const d=$('#modal');d.innerHTML='<div class="spread"><h2>'+title+'</h2>'+btn('close','','close','ghost','aria-label="'+t('关闭','Close')+'"')+'</div>'+body+(footer?'<div class="modal-footer">'+footer+'</div>':'');d.showModal();const zone=$('#dropzone');if(zone){zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');if(e.dataTransfer.files[0])loadFile(e.dataTransfer.files[0]);});}}
function commit(next,zh,en,code,newcols){if(next.length>20000)throw Error('LIMIT');undo.push({rows:structuredClone(rows),cols:[...cols],visible:[...visible],history:structuredClone(history),prepareMode,prepareDrafts:structuredClone(prepareDrafts)});if(undo.length>20)undo.shift();history.push({zh,en,code,before:rows.length,after:next.length,time:new Date().toISOString()});pending=null;groupSpec=null;rows=next;cols=newcols|| (rows.length?E.columns(rows):cols);visible=cols.filter(c=>visible.includes(c)||!undo.at(-1).cols.includes(c));if(sort&&!cols.includes(sort.key))sort=null;query='';page=0;analysisResult=null;render();toast(t('操作完成，可随时撤销。','Done. You can undo this operation.'));}
function error(e){const msg={EMPTY:t('文件中没有数据行。','The file has no data rows.'),CSV_QUOTE:t('CSV 引号未闭合，请检查格式。','CSV contains an unclosed quote.'),HEADERS:t('表头必须非空且不重复。','Headers must be non-empty and unique.'),CSV_WIDTH:t('CSV 数据行列数与表头不一致。','CSV row widths do not match the header.'),JSON_ROWS:t('JSON 必须为对象组成的数组。','JSON must be an array of objects.'),JSON_NESTED:t('JSON 字段必须为单个值，不能嵌套对象或数组。','JSON cells must be scalar values, not nested objects or arrays.'),LIMIT:t('文件超过 20,000 行或 80 列限制。','The file exceeds the limit of 20,000 rows or 80 columns.'),SIZE:t('文件不能超过 5 MB。','The file must be 5 MB or smaller.'),FORMAT:t('请选择 CSV、TSV、JSON 或 Excel 文件。','Choose a CSV, TSV, JSON or Excel file.'),NO_NUMERIC:t('该字段没有有效数值，无法按均值或中位数填充。','This column has no valid numbers for a mean or median.'),COLUMN_NAME:t('新字段名称不能为空或与现有字段重名。','The new column name must be non-empty and unique.'),VALUE:t('请填写有效的值。','Please enter a valid value.'),NUMERIC:t('此操作需要一个数值字段。','This operation requires a numeric field.')};toast(msg[e.message]||t('操作失败，请检查文件或输入内容。','Unable to complete. Check your file or input.'));console.warn(e.message);}
function setData(data,name,sample,replaceCurrent=false){
 if(activeDataset)datasets.save(activeDataset,captureDataset());
 pending=null;prepareMode='missing';prepareDrafts=null;prepareResult=null;joinData=null;joinName='';joinDatasetId='';workbook=null;rows=data;original=structuredClone(rows);cols=E.columns(rows);visible=[...cols];dataset=name;isSample=sample;history=[];undo=[];query='';sort=null;page=0;analysisResult=null;
 const config=initialConfig(rows);({chartType,chartX,chartY,chartAgg,chartColor,profileKey,groupSpec,timeKey,timeMetric,timeUnit}=config);
 if(replaceCurrent)datasets.save(activeDataset,captureDataset());else activeDataset=datasets.add(captureDataset());
 render();
}
function download(content,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const get=id=>$('#'+id)?.value;
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;e.preventDefault();const a=b.dataset.act;try{
 if(navs().some(n=>n[0]===a)||a==='help'){view=a;page=0;render();window.scrollTo(0,0);}
 else if(a==='menu')$('.sidebar').classList.toggle('open');
 else if(a==='language'){lang=lang==='zh'?'en':'zh';localStorage.setItem('datalens-language',lang);analysisResult=null;render();}
 else if(a==='close')$('#modal').close();
 else if(a==='import')modal(t('导入数据','Import data'),'<p class="card-sub">'+t('导入后新增一个数据集。可在左侧切换，每个数据集分别保留处理记录和图表设置。','Import adds a dataset. Switch in the sidebar; transformations and chart settings are retained separately.')+'</p><button type="button" id="dropzone" data-act="chooseFile" class="drop-zone" style="width:100%;display:block">'+icon('upload')+'<strong>'+t('拖拽文件到这里，或点击选择','Drop a file here, or click to browse')+'</strong><p>CSV / TSV / JSON / XLSX · UTF-8 · ≤ 5 MB</p></button><p class="card-sub">'+t('最多 20,000 行、80 列。CSV 首行为唯一表头；JSON 为对象数组。','Up to 20,000 rows and 80 columns. CSV needs unique headers; JSON must be an array of records.')+'</p>',btn('downloadSample',t('下载原始企鹅数据','Download original penguin CSV'),'download')+btn('sample',t('使用真实企鹅数据','Use penguin observations'),'spark','primary'));
 else if(a==='chooseFile')$('#fileInput').click();
 else if(a==='downloadSample')download(RAW_CSV,'penguins.csv','text/csv;charset=utf-8');
 else if(a==='sample'){const existing=datasets.list().find(d=>d.isSample);if(existing)switchDataset(existing.id);else setData(penguins(),'penguins.csv',true);$('#modal').close();}
 else if(a==='reset')modal(t('恢复原始数据？','Restore the original data?'),'<p style="margin-top:18px" class="muted">'+t('将撤回全部清洗操作，恢复到最近一次导入时的状态。','All transformations will be removed, restoring the last imported dataset.')+'</p>',btn('close',t('取消','Cancel'))+btn('confirmReset',t('恢复原始数据','Restore'),'reset','primary'));
 else if(a==='confirmReset'){setData(structuredClone(original),dataset,isSample,true);$('#modal').close();}
 else if(a==='undo'){prepareResult=null;pending=null;let s=undo.pop();if(s){prepareMode=s.prepareMode||prepareMode;prepareDrafts=s.prepareDrafts||prepareDrafts;rows=s.rows;cols=s.cols;visible=s.visible;history=s.history;analysisResult=null;query='';render();toast(t('已撤销上一步。','Last operation undone.'));}}
 else if(a==='export'){modal(t('导出当前结果','Export your results'),'<p class="card-sub" style="margin:16px 0">'+t('导出当前数据集的全部记录与可见列。','Exports all rows and visible columns from the working dataset.')+'</p><div class="status-bar">'+fmt(current().length)+' '+t('行','rows')+' × '+visible.length+' '+t('列','columns')+'</div>',btn('exportJSON','JSON','download')+btn('exportCSV','CSV','download','primary'));}
 else if(a==='exportCSV'){download(E.csv(current(),visible),'datalens_export.csv','text/csv;charset=utf-8');$('#modal').close();}
 else if(a==='exportJSON'){download(JSON.stringify(current().map(r=>Object.fromEntries(visible.map(c=>[c,r[c]]))),null,2),'datalens_export.json','application/json');$('#modal').close();}
 else if(a==='sort'){sort={key:b.dataset.key,dir:sort?.key===b.dataset.key&&sort.dir==='asc'?'desc':'asc'};if(view==='overview')view='data';page=0;render();}
 else if(a==='prev'||a==='next'){page+=a==='prev'?-1:1;render();}
 else if(a==='columns')modal(t('选择显示的列','Choose visible columns'),'<div class="check-list">'+cols.map((c,i)=>'<label><input type="checkbox" name="visibleCol" value="'+esc(c)+'" '+(visible.includes(c)?'checked':'')+'>'+esc(label(c))+'</label>').join('')+'</div>',btn('applyColumns',t('应用','Apply'),'check','primary'));
 else if(a==='applyColumns'){const selected=$$('input[name="visibleCol"]:checked').map(i=>i.value);if(!selected.length)throw Error('VALUE');visible=selected;$('#modal').close();render();}
 else if(a==='applyMissing'){let c=get('missingCol'),m=get('missingMethod'),v=get('missingValue');if(m==='custom'&&!v.trim())throw Error('VALUE');let next=m==='drop'?rows.filter(r=>!E.missing(r[c])):E.fillMissing(rows,c,m,v);commit(next,'处理缺失值：'+c,'Handle missing values: '+c,m==='drop'?'df.dropna(subset=['+JSON.stringify(c)+'])':'df['+JSON.stringify(c)+'].fillna('+(m==='custom'?JSON.stringify(E.scalar(v)):'df['+JSON.stringify(c)+'].'+m+'()')+')');}
 else if(a==='dedupe')commit(E.dedupe(rows,cols),'移除重复记录','Remove duplicate rows','df.drop_duplicates()');
 else if(a==='editColumn'){const c=get('editCol'),typ=get('editType'),name=get('renameValue').trim()||c;if(name!==c&&cols.includes(name))throw Error('COLUMN_NAME');let next=rows.map(r=>Object.fromEntries(cols.map(k=>{let v=r[k];if(k===c&&!E.missing(v)){if(typ==='number')v=Number.isFinite(Number(v))?Number(v):null;if(typ==='text')v=String(v);}return[k===c?name:k,v];})));commit(next,'调整字段：'+c,'Edit column: '+c,(typ==='number'?'pd.to_numeric(df['+JSON.stringify(c)+'], errors="coerce")':typ==='text'?'df['+JSON.stringify(c)+'].astype("string")':'')+(name!==c?'\ndf.rename(columns={'+JSON.stringify(c)+': '+JSON.stringify(name)+'})':''),cols.map(k=>k===c?name:k));}
 else if(a==='calculate'){let name=get('calcName').trim(),a=get('calcA'),b=get('calcB'),op=get('calcOp'),constant=b==='__constant'?get('calcConstant'):undefined;if(cols.length>=80)throw Error('LIMIT');if(constant!==undefined&&(constant===''||!Number.isFinite(Number(constant))))throw Error('VALUE');if(!a||!b)throw Error('NUMERIC');let next=E.compute(rows,name,a,op,b,constant);commit(next,'新增计算字段：'+name,'Calculate field: '+name,'df['+JSON.stringify(name)+'] = df['+JSON.stringify(a)+'] '+op+' '+(constant!==undefined?constant:'df['+JSON.stringify(b)+']')+(op==='/'?'  # replace division by zero with null':''));}
 else if(a==='aggregate'){let r=get('groupRow'),c=get('groupCol'),v=get('groupVal'),fn=get('groupAgg');if(fn!=='count'&&!colopts(true).some(([k])=>k===v))throw Error('NUMERIC');let data,headers;if(c){const p=E.pivot(rows,r,c,v,fn);if(p.keys.length>80)throw Error('LIMIT');headers=[label(r),...p.keys.map(k=>String(val(k)))];data=p.rows.map(r=>[r.key,...r.values]);}else{headers=[label(r),label(v)+' ('+fn+')'];data=E.groupBy(rows,r,v,fn).map(g=>[g.key,g.value]);}analysisResult={data,headers,title:label(r)+(c?' × '+label(c):'')+' / '+label(v)+' · '+fn};renderAnalysisResult();}
 else if(a==='exportAnalysis'){const {data,headers}=analysisResult;download(E.csv(data.map(r=>Object.fromEntries(r.map((v,i)=>[headers[i]+' ['+(i+1)+']',v])))),'datalens_analysis.csv','text/csv;charset=utf-8');}
 else if(a==='exportHistory')download(JSON.stringify({dataset,operations:history},null,2),'datalens_history.json','application/json');
 else if(a==='exportChart'){if(chartType==='heatmap'){const n=colopts(true).slice(0,10).map(o=>o[0]);download(E.csv(n.map(a=>Object.fromEntries([['column',a],...n.map(b=>[b,E.correlation(current(),a,b)])]))),'datalens_correlation.csv','text/csv;charset=utf-8');toast(t('热力图已导出为数值矩阵 CSV。','Heatmap exported as a numeric CSV matrix.'));}else{const svg=$('#mainChart svg');if(!svg)throw Error('NO_NUMERIC');let clone=svg.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.querySelectorAll('text').forEach(n=>{n.setAttribute('font-family','Microsoft YaHei, PingFang SC, Arial, sans-serif');n.setAttribute('font-size','11');if(!n.hasAttribute('fill'))n.setAttribute('fill','#65708a');});if(chartType==='donut'){clone.setAttribute('viewBox','0 0 520 220');clone.setAttribute('style','transform:none');clone.querySelectorAll('circle').forEach(n=>n.setAttribute('transform','rotate(-90 90 90)'));const legend=$$('#mainChart .legend-item');legend.forEach((el,i)=>{let text=document.createElementNS('http://www.w3.org/2000/svg','text');text.setAttribute('x','200');text.setAttribute('y',String(25+i*24));text.setAttribute('font-size','12');text.setAttribute('fill',color[i%color.length]);text.textContent=el.textContent;clone.append(text);});}if(chartType==='scatter'&&chartColor){const categories=[...new Set(rows.filter(r=>E.numeric(r[chartX])&&E.numeric(r[chartY])).map(r=>r[chartColor]))];clone.setAttribute('viewBox','0 0 740 '+(355+Math.ceil(categories.length/4)*20));categories.forEach((c,i)=>{const txt=document.createElementNS('http://www.w3.org/2000/svg','text');txt.setAttribute('x',String(50+(i%4)*170));txt.setAttribute('y',String(355+Math.floor(i/4)*20));txt.setAttribute('fill',color[i%color.length]);txt.setAttribute('font-size','12');txt.textContent=val(c);clone.append(txt);});}clone.querySelectorAll('[data-act]').forEach(n=>{n.removeAttribute('data-act');n.removeAttribute('tabindex');n.removeAttribute('role');});download(clone.outerHTML,'datalens_chart.svg','image/svg+xml');}}
 }catch(err){error(err);}});
document.addEventListener('change',e=>{if(e.target.id==='fileInput'&&e.target.files[0])loadFile(e.target.files[0]);});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;page=0;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
// Full-dataset exploration; transformations retain explicit previews.
let prepareMode='missing',prepareDrafts=null,prepareResult=null,prepareUpdateTimer=null;
let profileKey=null,pending=null,groupSpec=null,joinData=null,joinName='',joinDatasetId='',workbook=null,importMode='replace',timeUnit='month',timeMetric='revenue',timeKey='date',chartColor='species';
function dataView(){
 const prof=E.profile(rows,cols),missing=prof.reduce((a,c)=>a+c.missing,0);
 if(!cols.includes(profileKey))profileKey=prof.find(c=>c.type==='number'&&c.missing)?.key||prof.find(c=>c.type==='number')?.key||cols[0];
 return `${sourceCard(missing)}<section class="card card-pad quality-map"><h2>${t('缺失值分布','Missing-value map')}</h2><div class="wide-viz">${extras.qualityMap(rows,cols)}</div></section>
 <section class="card profile-workspace"><div class="profile-list"><div class="profile-list-title"><h2>${t('字段画像','Field profiles')}</h2><p class="card-sub">${t('完整数据集 · 点击字段探索','Full dataset · Choose a field')}</p></div>${prof.map(c=>`<div class="profile-item ${profileKey===c.key?'active':''}"><button class="profile-pick" data-act="profile" data-key="${esc(c.key)}"><span class="field-type">${c.type==='number'?'#':c.type==='date'?'◷':'Aa'}</span><span><b>${esc(label(c.key))}</b><small>${fmt(c.unique)} ${t('个唯一值','unique values')}</small></span></button>${c.missing?`<span class="missing-badge">${fmt(c.missing)} ${t('缺失','missing')}</span>`:'<span class="complete-dot" title="'+t('无缺失','Complete')+'">✓</span>'}</div>`).join('')}</div><div class="profile-detail" id="profileDetail"></div></section>${tableCard(tableRows())}`;
}
function distribution(data,key,_unused=data,{bins=null,max=null}={}){
 bins=bins||V.binsFor([data],key);if(!bins.length)return empty(t('该字段没有有效数值。','This field has no valid numbers.'));
 const counts=V.countBins(data,key,bins),peak=max||Math.max(1,...counts.map(d=>d.value));
 const W=700,H=220,L=40,R=15,T=22,B=35,w=(W-L-R)/bins.length,y=n=>H-B-n/peak*(H-T-B);
 return `<svg class="distribution" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(label(key))} ${t('频数分布','frequency distribution')}"><text x="${L}" y="13">${t('记录数','Records')}</text>${(peak>1?[0,.5,1]:[0,1]).map(f=>`<line x1="${L}" x2="${W-R}" y1="${y(peak*f)}" y2="${y(peak*f)}" stroke="#e4e7f3"/><text x="${L-7}" y="${y(peak*f)+4}" text-anchor="end">${fmt(peak*f)}</text>`).join('')}${bins.map((b,i)=>`<g><rect x="${L+i*w+3}" y="${y(counts[i].value)}" width="${Math.max(1,w-6)}" height="${H-B-y(counts[i].value)}" rx="3" fill="#4f46e5"/><title>${fmt(b.start,2)}–${fmt(b.end,2)}: ${counts[i].value}</title></g>`).join('')}<text x="${L}" y="${H-12}">${fmt(bins[0].start,2)}</text><text x="${W-R}" y="${H-12}" text-anchor="end">${fmt(bins.at(-1).end,2)}</text></svg>`;
}
function categoryPlot(key,base=rows){
 const groups=new Map();for(const r of base){const k=JSON.stringify(r[key]??null);if(!groups.has(k))groups.set(k,{value:r[key],count:0});groups.get(k).count++;}
 const all=[...groups.values()].sort((a,b)=>b.count-a.count),list=all.slice(0,8),max=Math.max(1,...list.map(g=>g.count));
 return '<div class="category-facets">'+list.map(g=>`<div class="facet-row"><span class="facet-name">${esc(val(g.value))}</span><span class="facet-track"><b style="width:${100*g.count/max}%"></b></span><span class="facet-count">${fmt(g.count)}</span></div>`).join('')+'</div>'+(all.length>8?`<p class="card-sub">${t('按完整数据频数展示前 8 类，共 ','Top 8 categories by full-dataset frequency; ')}${all.length}${t(' 类。其余记录仍保留在工作表中。',' categories total. Other records remain in the table.')} </p>`:'');
}
function boxPlot(key,data=current()){
 const s=V.outliers(data,key);if(!s.count)return fieldEmpty(null,key);
 const vals=data.map(r=>r[key]).filter(E.numeric),inside=vals.filter(v=>v>=s.lower&&v<=s.upper),lo=Math.min(...inside),hi=Math.max(...inside),x=v=>45+(v-s.min)/(s.max-s.min||1)*600;
 const out=vals.filter(v=>v<s.lower||v>s.upper);
 return `<svg viewBox="0 0 700 120" role="group" aria-label="${esc(label(key))} ${t('箱线图','box plot')}"><line x1="${x(lo)}" x2="${x(hi)}" y1="50" y2="50" stroke="#7768cf" stroke-width="2"/><path d="M${x(lo)} 36v28M${x(hi)} 36v28" stroke="#7768cf" stroke-width="2"/><rect x="${x(s.q1)}" y="29" width="${Math.max(2,x(s.q3)-x(s.q1))}" height="42" fill="#e6e1ff" stroke="#4f46e5"/><line x1="${x(s.median)}" x2="${x(s.median)}" y1="29" y2="71" stroke="#4f46e5" stroke-width="3"/>${[...new Set(out)].slice(0,300).map(v=>`<circle aria-label="${t('检查数值','Inspect value')} ${v}" cx="${x(v)}" cy="50" r="5" fill="#e7673e"><title>${v}</title></circle>`).join('')}<text x="45" y="100">${fmt(s.min,2)}</text><text x="350" y="100" text-anchor="middle">${t('中位数','Median')} ${fmt(s.median,2)}</text><text x="645" y="100" text-anchor="end">${fmt(s.max,2)}</text></svg><div class="spread"><p class="card-sub">${t('1.5 × IQR 标记疑似异常，需结合业务检查。','1.5 × IQR flags potential outliers; inspect in context.')}</p>${out.length?`<span class="badge">${fmt(out.length)} ${t('条疑似异常','potential outliers')}</span>`:''}</div>`;
}
function renderProfile(){const p=E.profile(rows,cols).find(c=>c.key===profileKey);if(!p)return;
 const stats=E.describe(rows.map(r=>r[profileKey]));
 $('#profileDetail').innerHTML=`<div class="card-head"><div><h2>${esc(label(profileKey))}</h2></div>${btn('clean',t('整理数据','Prepare data'),'chevron','small')}</div><p class="card-sub">${t('统计当前数据集的全部记录。','Statistics use the full working dataset.')}</p>${p.type==='number'?`<div class="inline-stats"><span>${t('有效值','Valid values')} <b>${fmt(stats.count)}</b></span><span>${t('均值','Mean')} <b>${fmt(stats.mean,2)}</b></span><span>${t('中位数','Median')} <b>${fmt(stats.median,2)}</b></span></div><div class="chart">${distribution(rows,profileKey)}</div><div class="chart box-chart">${boxPlot(profileKey)}</div>`:categoryPlot(profileKey)}`;
}
const prepareTabs=()=>[['missing','alert',t('缺失值处理','Missing values')],['duplicates','rows',t('重复数据处理','Duplicates')],['rename','columns',t('字段名称替换','Rename columns')],['calculate','plus',t('加入新字段','Add a field')]];
function cleanView(){return `<div class="prepare-tabs" role="tablist" aria-label="${t('数据处理功能','Preparation tools')}">${prepareTabs().map(([key,ic,text])=>btn('prepareMode',text,ic,'prepare-tab '+(prepareMode===key?'active':''),`role="tab" aria-selected="${prepareMode===key}" tabindex="${prepareMode===key?0:-1}" aria-controls="preparePanel" id="prepareTab-${key}" data-mode="${key}"`)).join('')}</div><section class="card prepare-panel" id="preparePanel" role="tabpanel" aria-labelledby="prepareTab-${prepareMode}"><div class="prepare-scope">${icon('shield')}<span>${t('作用范围：当前数据集全部 ','Scope: all ')}<b>${fmt(rows.length)}</b> ${t('行。参数调整只更新预览，应用后可撤销。','rows. Parameter changes update the preview; applied changes can be undone.')}</span></div><div class="prepare-workspace"><aside class="prepare-controls" id="prepareControls"></aside><div class="prepare-result"><div id="prepareStage" aria-live="off"></div><div id="prepareActionBar" class="prepare-action-bar" aria-live="polite"></div></div></div></section><details class="prepare-join" ${joinData?'open':''}><summary>${t('多表合并','Join tables')}</summary>${joinPanel()}<div id="cleanPreview" aria-live="polite"></div></details>`;}
function prepareControls(){const d=prepareDrafts[prepareMode],nums=colopts(true);
 if(prepareMode==='missing'){const numeric=nums.some(o=>o[0]===d.column);return field(t('处理字段','Column'),select('missingCol',colopts(),d.column))+field(t('处理方式','Method'),select('missingMethod',[...(numeric?[['mean',t('均值填充','Fill mean')],['median',t('中位数填充','Fill median')]]:[]),['custom',t('自定义填充','Custom fill')],['drop',t('删除缺失行','Drop missing rows')]],d.method))+field(t('填充值','Fill value'),`<input id="missingValue" value="${esc(d.value)}" ${d.method==='custom'?'':'disabled'} placeholder="${t('仅自定义填充时填写','For custom fill only')}">`)+`<p class="prepare-control-note">${t('缺失包括空单元格；处理仅作用于所选字段。删除缺失行会移除整条记录。','Empty cells count as missing. Filling affects the chosen field; dropping removes the entire row.')}</p><span class="code-tag">fillna / dropna</span>`;}
 if(prepareMode==='duplicates'){const count=rows.length-E.dedupe(rows,cols).length;return `<div class="prepare-dedupe-count"><b>${fmt(count)}</b><span>${t('条重复记录','duplicate rows')}</span></div><p class="prepare-control-note">${t('比较全部 ','Compare all ')}${cols.length}${t(' 个字段，内容完全相同的记录仅保留第一次出现的一条。',' fields; keep the first row for each exact duplicate.')}</p><span class="code-tag">drop_duplicates</span>`;}
 if(prepareMode==='rename')return field(t('原字段','Column'),select('editCol',colopts(),d.column))+field(t('新字段名称','New name'),`<input id="renameValue" value="${esc(d.name)}" placeholder="${t('输入新名称','Enter a new name')}">`)+field(t('字段类型（可选）','Type (optional)'),select('editType',[['keep',t('保持原类型','Keep type')],['number',t('转换为数值','Convert to number')],['text',t('转换为文本','Convert to text')]],d.type))+`<p class="prepare-control-note">${t('新名称必须唯一。更名保留字段顺序与数值；转换失败的数值将成为缺失值。','Names must be unique. Renaming preserves column order and values; failed numeric conversions become null.')}</p><span class="code-tag">rename / astype</span>`;
 return field(t('左侧字段','Left field'),select('calcA',nums,d.a))+`<div class="prepare-small-row">${field(t('运算','Operator'),select('calcOp',[['+','+'],['-','−'],['*','×'],['/','÷']],d.op))}${field(t('右侧字段','Right field'),select('calcB',[...nums,['__constant',t('使用常数','Constant')]],d.b))}</div>`+field(t('常数','Constant'),`<input id="calcConstant" type="number" value="${esc(d.constant)}" ${d.b==='__constant'?'':'disabled'}>`)+field(t('新字段名称','New field name'),`<input id="calcName" value="${esc(d.name)}" placeholder="new_measure">`)+`<p class="prepare-control-note">${t('逐行计算；缺失输入、除零和非有限结果返回空值。','Calculated per row. Missing inputs, division by zero and non-finite results return null.')}</p><span class="code-tag">assign</span>`;
}
function readPrepareDraft(){const d=prepareDrafts[prepareMode];if(prepareMode==='missing')Object.assign(d,{column:get('missingCol'),method:get('missingMethod'),value:get('missingValue')});if(prepareMode==='rename')Object.assign(d,{column:get('editCol'),name:get('renameValue'),type:get('editType')});if(prepareMode==='calculate')Object.assign(d,{a:get('calcA'),op:get('calcOp'),b:get('calcB'),constant:get('calcConstant'),name:get('calcName')});}
function renderPrepare(controls=true){if(!$('#prepareStage'))return;clearTimeout(prepareUpdateTimer);prepareDrafts=P.reconcilePrepareDrafts(rows,cols,prepareDrafts);if(controls)$('#prepareControls').innerHTML=prepareControls();
 const joinPending=pending&&pending.kind!=='prepare'?pending:null;let result,problem='',applied=prepareResult?.mode===prepareMode;
 try{result=applied?prepareResult:P.previewPrepare(rows,cols,prepareMode,prepareDrafts[prepareMode]);}catch(e){problem=e.message;}
 if(joinPending)pending=joinPending;else pending=null;
 const titles={missing:t('缺失数量与分布','Missing values & distribution'),duplicates:t('重复记录去向','Duplicate disposition'),rename:t('字段映射','Column mapping'),calculate:t('计算结果','Calculated results')};
 if(problem){const messages={COLUMN_NAME:t('请填写一个不与已有字段重名的新名称。','Enter a new, unique column name.'),VALUE:t('请补全参数以生成预览。','Complete the parameters to preview.'),NUMERIC:t('此计算需要数值字段，请先检查字段类型。','This calculation requires numeric fields.'),NO_NUMERIC:t('该字段没有数值，改用自定义填充或删除缺失行。','No numeric values. Use custom fill or drop missing rows.'),LIMIT:t('最多支持 80 个字段。','A maximum of 80 fields is supported.')};$('#prepareStage').dataset.state='error';$('#prepareStage').innerHTML=`<div class="prepare-stage-head"><h2>${titles[prepareMode]}</h2><span class="badge">${t('待完善参数','Parameters needed')}</span></div><div class="prepare-validation">${icon('help')}<p>${messages[problem]||t('请检查字段和输入参数。','Check the fields and parameters.')}</p></div>`;$('#prepareActionBar').innerHTML=btn('applyPrepared',t('应用处理','Apply changes'),'check','primary','disabled');return;}
 if(!applied&&!result.noChange&&!joinPending){const title=prepareTabs().find(x=>x[0]===prepareMode)[2];pending={kind:'prepare',next:result.after,newcols:result.afterCols,key:result.key,afterKey:result.afterKey,zh:lang==='zh'?title:prepareTabsChinese[prepareMode],en:prepareTabsEnglish[prepareMode],code:result.code,result};}
 $('#prepareStage').dataset.state=applied?'applied':'preview';$('#prepareStage').innerHTML=`<div class="prepare-stage-head"><h2>${titles[prepareMode]}</h2><span class="badge ${applied?'applied-badge':''}">${applied?t('已应用','Applied'):t('预览 · 未应用','Preview · Not applied')}</span></div>${prepareVisuals.render(result)}`;
 const summary=joinPending?t('请先应用或取消下方的合并预览。','Apply or cancel the join preview below first.'):applied?t('已应用到当前数据集，可以使用顶部撤销。','Applied to this dataset. Use Undo above to revert.'):result.noChange?t('当前设置不会改变数据。','These settings do not change the data.'):t('预览已更新，确认后再应用。','Preview updated. Apply when ready.');
 $('#prepareActionBar').innerHTML=`<span>${summary}</span><div class="flex">${btn('resetPrepareDraft',t('恢复本项设置','Reset parameters'),'reset','small ghost')}${btn('applyPrepared',applied?t('已应用','Applied'):t('应用处理','Apply changes'),'check','primary',applied||result.noChange||joinPending?'disabled':'')}</div>`;
}
const prepareTabsChinese={missing:'缺失值处理',duplicates:'重复数据处理',rename:'字段名称替换',calculate:'加入新字段'},prepareTabsEnglish={missing:'Handle missing values',duplicates:'Remove duplicates',rename:'Rename columns',calculate:'Add a calculated field'};
function updatePrepareInput(e){if(view!=='clean'||!e.target.closest('#prepareControls'))return;readPrepareDraft();prepareResult=null;pending=null;$('#cleanPreview').innerHTML='';clearTimeout(prepareUpdateTimer);const id=activeDataset,mode=prepareMode;
 if(e.type==='change'){renderPrepare(['missingCol','missingMethod','editCol','calcB'].includes(e.target.id));return;}
 $('#prepareActionBar').innerHTML=`<span>${t('正在更新预览…','Updating preview…')}</span>${btn('applyPrepared',t('应用处理','Apply changes'),'check','primary','disabled')}`;prepareUpdateTimer=setTimeout(()=>{if(view==='clean'&&activeDataset===id&&prepareMode===mode)renderPrepare(false);},150);
}
document.addEventListener('input',updatePrepareInput);document.addEventListener('change',updatePrepareInput);
document.addEventListener('keydown',e=>{const tab=e.target.closest('.prepare-tab');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const modes=prepareTabs().map(x=>x[0]),i=modes.indexOf(prepareMode),next=e.key==='Home'?0:e.key==='End'?modes.length-1:(i+(e.key==='ArrowRight'?1:-1)+modes.length)%modes.length;clearTimeout(prepareUpdateTimer);prepareMode=modes[next];pending=null;render();$('#prepareTab-'+prepareMode).focus();});


function joinPanel(){return `<section class="card card-pad join-panel"><div class="spread"><div><h2>${t('合并另一张表','Join another table')}</h2><p class="card-sub">${t('按键匹配，预览匹配率和新增行；空键不匹配，数字与文本键区分类型。','Match keys and preview coverage and expanded rows. Null keys do not match; numeric and text keys are distinct.')}</p></div>${btn('joinFile',t('选择文件','Choose file'),'upload','small')}</div>${datasetJoinPicker()}${joinData?`<p class="card-sub">${esc(joinName)} · ${joinData.length} ${t('行','rows')}</p><div class="form-row">${field(t('当前表关联键','Current table key'),select('joinLeft',colopts()))}${field(t('另一表关联键','Other table key'),select('joinRight',E.columns(joinData).map(k=>[k,k])))}${field(t('合并方式','Join type'),select('joinHow',[['left',t('左连接 · 保留当前表所有行','Left · Keep all current rows')],['inner',t('内连接 · 仅匹配行','Inner · Matching rows only')]]))}${btn('previewJoin',t('预览合并','Preview join'),'analysis','primary')}</div>`:`<p class="card-sub join-hint">CSV / TSV / JSON / XLSX · ${t('支持一对多匹配；结果最多 20,000 行。','One-to-many matches supported; at most 20,000 result rows.')}</p>`}</section>`;}
function prepareAction(a){if(a!=='previewJoin'||!joinData)return;const j=V.join(rows,joinData,get('joinLeft'),get('joinRight'),get('joinHow')),key=colopts(true)[0]?.[0]||cols[0];pending={kind:'join',next:j.rows,key,afterKey:key,newcols:j.cols,zh:'合并表格：'+joinName,en:'Join table: '+joinName,code:`df.merge(other, left_on=${JSON.stringify(get('joinLeft'))}, right_on=${JSON.stringify(get('joinRight'))}, how=${JSON.stringify(get('joinHow'))})`,join:j};showPreview();renderPrepare(false);$('#cleanPreview').scrollIntoView({behavior:'smooth',block:'start'});}
function showPreview(){if(!pending||!$('#cleanPreview'))return;const {next,key,afterKey,join}=pending;
 const before=rows.map(r=>({value:r[key]})),after=next.map(r=>({value:r[afterKey]})),bins=V.binsFor([before,after],'value'),b=E.describe(before.map(r=>r.value)),a=E.describe(after.map(r=>r.value));
 const max=Math.max(1,...V.countBins(before,'value',bins).map(d=>d.value),...V.countBins(after,'value',bins).map(d=>d.value));
 const mini=(title,data,stats)=>`<div><h3>${title}</h3><div class="inline-stats"><span>${t('行数','Rows')} <b>${data.length}</b></span><span>${t('缺失','Missing')} <b>${data.filter(r=>E.missing(r.value)).length}</b></span><span>${t('均值','Mean')} <b>${fmt(stats.mean,2)}</b></span></div><div class="chart">${bins.length?distribution(data,'value',data,{interactive:false,bins,max}):empty(t('非数值字段：请查看下方记录预览。','Non-numeric field: inspect the record preview below.'))}</div></div>`;
 const changes=[];if(!join&&next.length===rows.length)for(let i=0;i<next.length&&changes.length<8;i++){if(JSON.stringify(rows[i])!==JSON.stringify(next[i]))changes.push([i+1,rows[i][key],next[i][afterKey]]);}
 $('#cleanPreview').innerHTML=`<section class="card card-pad preview-panel"><div class="spread"><div><h2>${esc(t(pending.zh,pending.en))}</h2></div>${btn('cancelPreview',t('取消预览','Cancel preview'),'close','small')}</div>${join?`<div class="inline-stats"><span>${t('匹配原表行','Matched source rows')} <b>${join.matched}</b></span><span>${t('未匹配','Unmatched')} <b>${join.unmatched}</b></span><span>${t('一对多新增行','Extra rows from multiple matches')} <b>${join.extra}</b></span></div>`:''}<p class="card-sub">${t('比较字段','Comparison field')}: ${esc(label(key))} · ${t('左右使用相同坐标范围、分箱和频数上限。','Both sides share bin boundaries and axis scales.')}</p><div class="preview-quality wide-viz">${extras.qualityChange(rows,next,cols,pending.newcols||cols)}</div><div class="comparison-grid">${mini(t('处理前','Before'),before,b)}${mini(t('处理后','After'),after,a)}</div>${changes.length?`<div class="table-scroll"><table><thead><tr><th>${t('原行号','Source row')}</th><th>${t('原值','Before')}</th><th>${t('新值','After')}</th></tr></thead><tbody>${changes.map(r=>'<tr>'+r.map(v=>'<td>'+esc(E.numeric(v)?fmt(v,3):val(v))+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`:`<p class="card-sub">${t('结果行数','Result rows')}: ${rows.length} → ${next.length}</p>`}${join?`<div class="table-scroll"><table><thead><tr>${(pending.newcols||cols).map(k=>'<th>'+esc(label(k))+'</th>').join('')}</tr></thead><tbody>${next.slice(0,5).map(r=>'<tr>'+(pending.newcols||cols).map(k=>'<td>'+esc(val(r[k]))+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`:''}<div class="preview-footer"><p class="card-sub">${t('确认效果后应用；完成后可以撤销。','Apply after reviewing. You can undo the operation.')}</p>${btn('confirmPreview',t('应用这次处理','Apply transformation'),'check','primary')}</div></section>`;
}
function matrix(){const n=colopts(true).slice(0,10).map(o=>o[0]);if(!n.length)return empty(t('需要数值字段。','Numeric columns required.'));
 return `<p class="card-sub">${t('点击色块，查看该字段对的散点分布。','Click a cell to inspect the pair in a scatter plot.')}</p><div class="table-scroll"><table class="matrix"><thead><tr><th></th>${n.map(k=>'<th>'+esc(label(k))+'</th>').join('')}</tr></thead><tbody>${n.map(a=>'<tr><th>'+esc(label(a))+'</th>'+n.map(b=>{const r=E.correlation(current(),a,b);return `<td style="background:${r===null?'#fafafa':r>=0?'rgba(79,70,229,'+(.06+Math.abs(r)*.45)+')':'rgba(231,103,62,'+(.06+Math.abs(r)*.45)+')'}"><button class="matrix-cell" data-act="correlationPair" data-x="${esc(a)}" data-y="${esc(b)}" aria-label="${esc(label(a)+' / '+label(b))}: ${fmt(r,2)}">${fmt(r,2)}</button></td>`;}).join('')+'</tr>').join('')}</tbody></table></div><p class="card-sub">${t('负相关 −1（暖色） → 0 → +1 正相关（靛蓝色） · 最多显示 10 个数值字段','Negative −1 (warm) → 0 → +1 positive (indigo) · Up to 10 numeric fields')}</p>`;
}
function renderAnalysisResult(){
 if(!$('#analysisResult'))return;if(!groupSpec)groupSpec=initialConfig(rows).groupSpec;const {r,c,v,fn}=groupSpec;if(!cols.includes(r)||!cols.includes(v)){groupSpec=initialConfig(rows).groupSpec;return;}
 let data,headers;if(c){const p=E.pivot(current(),r,c,v,fn);headers=[label(r),...p.keys.map(k=>String(val(k)))];data=p.rows.map(r=>[r.key,...r.values]);}else{const groups=E.groupBy(current(),r,v,fn);headers=[label(r),label(v)+' ('+(aggopts().find(o=>o[0]===fn)?.[1]||fn)+')',t('记录数','Rows')];data=groups.map(g=>[g.key,g.value,g.count]);}
 analysisResult={data,headers,title:label(r)+' / '+label(v)};renderAnalysisTable();
 const categories=categoryFields(),other=categories.find(o=>o[0]!==r)?.[0],hasNumber=colopts(true).some(o=>o[0]===v),parts=[];
 if(hasNumber)parts.push('<section><h3>'+t('分组分布','Grouped distribution')+' · '+esc(label(v))+'</h3>'+extras.groupBoxes(current(),r,v)+'</section>');
 if(other)parts.push('<section><h3>'+t('类别构成占比','Category composition')+' · '+esc(label(other))+'</h3>'+extras.stacked(current(),r,other)+'</section>');
 if(!parts.length){const groups=E.groupBy(current(),r,v,fn),chart='<div class="chart">'+svgChart(groups.slice(0,24),'bar',label(v),label(r))+'</div>';parts.push(chart);}
 $('#analysisResult').insertAdjacentHTML('afterbegin','<div class="analysis-viz-grid">'+parts.join('')+'</div>');
}

function timePanel(){const dates=E.profile(rows,cols).filter(c=>c.type==='date').map(c=>[c.key,label(c.key)]),nums=colopts(true);if(!dates.length||!nums.length)return '';if(!dates.some(x=>x[0]===timeKey))timeKey=dates[0][0];if(!nums.some(x=>x[0]===timeMetric))timeMetric=nums[0][0];
 const g=V.timeGroups(current(),timeKey,timeMetric,'sum',timeUnit);
 return `<section class="card card-pad"><div class="card-head"><div><h2>${t('时间趋势','Time trends')}</h2><p class="card-sub">${t('按时间求和；未出现的时段不填零。周以周一为起点。','Totals by period; absent periods are not filled with zero. Weeks start Monday.')}</p></div></div><div class="form-row">${field(t('日期字段','Date field'),select('timeKey',dates,timeKey))}${field(t('时间指标','Time metric'),select('timeMetric',nums,timeMetric))}${field(t('时间粒度','Time interval'),select('timeUnit',[['day',t('日','Day')],['week',t('周','Week')],['month',t('月','Month')],['year',t('年','Year')]],timeUnit))}</div><div class="chart">${svgChart(g.slice(0,60),'line',label(timeMetric),label(timeKey))}</div>${g.length>60?'<p class="card-sub">'+t('仅展示最早 60 个时段。','Showing the earliest 60 periods.')+'</p>':''}</section>`;
}
function chartsView(){const n=colopts(true),cat=categoryFields();if(['groupbox','stacked','categoryHeatmap'].includes(chartType)&&!cat.some(o=>o[0]===chartX))chartX=cat[0]?.[0]||cols[0];if(['stacked','categoryHeatmap'].includes(chartType)&&chartColor===chartX)chartColor=cat.find(o=>o[0]!==chartX)?.[0]||'';
 if(!cols.includes(chartX))chartX=cols[0];if(chartAgg==='count'&&!['scatter','hist','box'].includes(chartType)){if(!cols.includes(chartY))chartY=cols[0];}else if(!n.some(o=>o[0]===chartY))chartY=n[0]?.[0]||cols[0];if(chartColor&&!cat.some(o=>o[0]===chartColor))chartColor=cat[0]?.[0]||'';
 return `<div class="explore-workspace"><section class="card explore-main"><div class="chart-options">${field(t('图表类型','Chart type'),select('chartType',[['bar',t('柱状图','Bar chart')],['line',t('折线图','Line chart')],['hist',t('直方图','Histogram')],['scatter',t('散点图','Scatter plot')],['box',t('箱线图','Box plot')],['donut',t('环形图','Donut chart')],['heatmap',t('相关性热力图','Correlation heatmap')],['groupbox',t('分组箱线与观测点','Grouped box & strip')],['stacked',t('百分比堆叠图','100% stacked bars')],['categoryHeatmap',t('类别交叉热力图','Category count heatmap')],['parallel',t('平行坐标','Parallel coordinates')],['scattermatrix',t('散点矩阵','Scatterplot matrix')]],chartType))}${field(t('X 轴 / 分组','X axis / Group'),select('chartX',colopts(),chartX))}${field(t('Y 轴 / 数值','Y axis / Value'),select('chartY',chartAgg==='count'&&!['scatter','hist','box'].includes(chartType)?colopts():n,chartY))}${field(t('统计方式','Aggregation'),select('chartAgg',aggopts(),chartAgg))}${field(t('类别 / 颜色分组','Category / Color group'),select('chartColor',[['',t('统一颜色','Single color')],...cat],chartColor))}</div><div class="card-pad"><div class="card-head"><div><h2 id="chartTitle"></h2></div><div class="flex">${btn('recommend',t('推荐图表','Suggest chart'),'spark','small')}${btn('exportChart',t('导出图表 SVG','Export chart SVG'),'download','small')}</div></div><div id="mainChart" class="chart-large"><div class="chart"></div></div><div id="chartEvidence" class="chart-evidence"></div><div class="chart-note"><span id="chartNote"></span></div></div></section><aside id="linkedPanels" class="linked-grid"></aside></div>`;
}
function renderMainChart(){const target=$('#mainChart .chart');if(!target)return;
 $('#chartX').disabled=['hist','box','heatmap','parallel','scattermatrix'].includes(chartType);$('#chartY').disabled=['heatmap','stacked','categoryHeatmap','parallel','scattermatrix'].includes(chartType);$('#chartAgg').disabled=!['bar','line','donut'].includes(chartType);$('#chartColor').disabled=!['scatter','stacked','categoryHeatmap','parallel','scattermatrix'].includes(chartType);
 $('[data-act=exportChart]').innerHTML=icon('download')+(chartType==='heatmap'?t('导出矩阵 CSV','Export matrix CSV'):t('导出图表 SVG','Export chart SVG'));
 $('#chartTitle').textContent=['hist','box'].includes(chartType)?label(chartY):label(chartY||'')+' / '+label(chartX||'');
 let note=t('图表与统计使用当前数据集的全部记录。','Charts and statistics use the complete working dataset.');
 if(['groupbox','stacked','categoryHeatmap','parallel','scattermatrix'].includes(chartType)){const titles={groupbox:t('分组箱线与观测点','Grouped box & strip'),stacked:t('类别构成占比','Category composition'),categoryHeatmap:t('类别交叉频数','Category counts'),parallel:t('平行坐标','Parallel coordinates'),scattermatrix:t('散点矩阵','Scatterplot matrix')};$('#chartTitle').textContent=titles[chartType];const keys=C.numericFields(rows,cols);target.innerHTML=chartType==='groupbox'?extras.groupBoxes(current(),chartX,chartY):chartType==='stacked'?extras.stacked(current(),chartX,chartColor):chartType==='categoryHeatmap'?extras.categoryHeatmap(current(),chartX,chartColor):chartType==='parallel'?extras.parallel(rows,current(),keys,chartColor):extras.scatterMatrix(current(),keys,chartColor);note='';}
 else if(chartType==='heatmap')target.innerHTML=matrix();
 else if(chartType==='hist'){target.innerHTML=distribution(rows,chartY,current());note=t('按区间统计全部有效数值的频数。','Counts all valid numeric values by interval.');}
 else if(chartType==='box'){target.innerHTML=boxPlot(chartY);note=t('橙色点表示疑似异常值；疑似异常不等于错误。','Orange points indicate potential outliers. A potential outlier is not necessarily an error.');}
 else if(chartType==='scatter'){target.innerHTML=scatter();note=t('每个点表示一条有效观测，点击可查看记录详情。超过 1,500 点时抽样显示，统计仍使用全部有效记录。','Each point represents a valid observation; click to inspect its details. Above 1,500 points the display is sampled; statistics use all valid rows.');}
 else{if(chartAgg!=='count'&&!colopts(true).some(([k])=>k===chartY)){target.innerHTML=empty(t('请选择数值字段。','Choose a numeric field.'));return;}const date=E.profile(rows,cols).find(c=>c.key===chartX)?.type==='date';let g=E.groupBy(current(),chartX,chartY,chartAgg,date);g.sort(chartType==='line'?(a,b)=>String(a.key).localeCompare(String(b.key),undefined,{numeric:true}):(a,b)=>(b.value??0)-(a.value??0));const max=chartType==='donut'?8:24;if(chartType==='donut')g=g.filter(d=>E.numeric(d.value)&&d.value>0);if(g.length>max)note+=' '+t('图中仅展示前 ','Chart shows the first ')+max+t(' 组，明细与导出仍包含全部记录。',' groups; records and data export retain all rows.');g=g.slice(0,max);target.innerHTML=chartType==='donut'?donut(g):svgChart(g,chartType,label(chartY),label(chartX));if(date)note+=' '+t('日期按月汇总。','Dates are grouped by month.');if(chartType==='donut')note+=' '+t('环形图仅含正值分组。','Donut includes positive groups only.');}
 const selected=current(),pairs=selected.filter(r=>E.numeric(r[chartX])&&E.numeric(r[chartY]));
 $('#chartEvidence').innerHTML=chartType==='scatter'?
 '<span>'+t('有效成对观测','Valid paired observations')+' <b>'+fmt(pairs.length)+' / '+fmt(selected.length)+'</b></span><span>Pearson r <b>'+fmt(E.correlation(selected,chartX,chartY),3)+'</b></span><small>'+t('使用全部有效配对 · 相关不代表因果','Uses all valid pairs · Correlation is not causation')+'</small>':
 '<span>'+t('当前数据集','Current dataset')+' <b>'+fmt(selected.length)+'</b> '+t('条记录','rows')+'</span>'+(['bar','line','donut'].includes(chartType)?'<span>'+t('统计方式','Aggregation')+' <b>'+esc(aggopts().find(o=>o[0]===chartAgg)?.[1]||chartAgg)+'</b></span>':'');
 $('#chartNote').textContent=note;
 const p=E.profile(rows,cols),cat=p.find(c=>c.key===chartColor)||p.find(c=>c.type==='text'&&c.unique<=30),num=p.find(c=>c.key===chartY&&c.type==='number')||p.find(c=>c.type==='number');
 $('#linkedPanels').innerHTML=(cat?`<section class="card card-pad"><h2>${esc(label(cat.key))} · ${t('记录构成','Record composition')}</h2><p class="card-sub">${t('各类别的全部记录数','Total records in each category')}</p>${categoryPlot(cat.key)}</section>`:'')+(num?`<section class="card card-pad"><h2>${esc(label(num.key))} · ${t('数值分布','Numeric distribution')}</h2><p class="card-sub">${t('当前数据集的全部有效数值','All valid values in the working dataset')}</p><div class="chart">${distribution(rows,num.key,current())}</div></section>`:'');
}
function scatter(){const all=rows.filter(r=>E.numeric(r[chartX])&&E.numeric(r[chartY]));if(!all.length)return empty(t('请选择两个数值字段。','Select two numeric fields.'));
 const xs=E.describe(all.map(r=>r[chartX])),ys=E.describe(all.map(r=>r[chartY])),W=740,H=340,L=65,R=20,T=20,B=45;
 const xmin=xs.min,xmax=xs.max===xs.min?xs.max+1:xs.max,ymin=ys.min,ymax=ys.max===ys.min?ys.max+1:ys.max;
 const x=v=>L+(v-xmin)/(xmax-xmin)*(W-L-R),y=v=>H-B-(v-ymin)/(ymax-ymin)*(H-B-T),cats=[...new Set(all.map(r=>r[chartColor]))];
 const step=Math.max(1,Math.ceil(all.length/1500)),plot=all.filter((_,i)=>i%step===0),index=new Map(rows.map((r,i)=>[r,i]));
 return `<svg id="scatterSvg" viewBox="0 0 ${W} ${H}" role="group" aria-label="${esc(label(chartX)+' / '+label(chartY))}"><rect width="${W}" height="${H}" fill="white"/>${[0,.25,.5,.75,1].map(f=>`<line x1="${L}" x2="${W-R}" y1="${y(ymin+(ymax-ymin)*f)}" y2="${y(ymin+(ymax-ymin)*f)}" stroke="#e4e7f3"/><text x="${L-9}" y="${y(ymin+(ymax-ymin)*f)+4}" text-anchor="end">${short(ymin+(ymax-ymin)*f)}</text><text x="${x(xmin+(xmax-xmin)*f)}" y="${H-20}" text-anchor="middle">${short(xmin+(xmax-xmin)*f)}</text>`).join('')}${plot.map(r=>`<circle class="scatter-point" data-act="inspectRow" data-row="${index.get(r)}" tabindex="0" role="button" aria-label="${t('检查第','Inspect row ')} ${index.get(r)+1}${t('行','')}" cx="${x(r[chartX])}" cy="${y(r[chartY])}" r="4" fill="${color[(chartColor?cats.indexOf(r[chartColor]):0)%color.length]}" opacity=".75"><title>${esc(label(chartX))}: ${fmt(r[chartX],2)}; ${esc(label(chartY))}: ${fmt(r[chartY],2)}${chartColor?' · '+esc(val(r[chartColor])):''}</title></circle>`).join('')}<text x="${L}" y="12">${esc(shortLabel(label(chartY)))}</text><text x="${W-R}" y="${H-3}" text-anchor="end">${esc(shortLabel(label(chartX)))}</text></svg>${chartColor?`<div class="scatter-legend">${cats.map((c,i)=>`<span><i style="background:${color[i%color.length]}"></i>${esc(val(c))}</span>`).join('')}</div>`:''}`;
}
function helpView(){return `<section class="card card-pad"><h2>${t('功能说明','Features')}</h2><div class="guide-steps">${[[t('数据','Data'),t('导入文件、查看质量与分布；搜索只查找工作表记录。','Import files and inspect quality and distributions. Search only locates worksheet rows.')],[t('处理','Prepare'),t('预览缺失填补、去重、更名、计算列，再确认应用；支持撤销。','Preview filling, deduplication, renaming and calculations before applying. Applied changes can be undone.')],[t('分析','Analyze'),t('基于完整数据进行统计、分组、透视、相关性和时间分析。','Describe, group, pivot and analyze correlations and time using the full dataset.')],[t('图表','Charts'),t('选择 12 类图形并配置字段；点击观测点查看记录详情。','Choose from 12 chart types and configure fields. Click observation points to inspect record details.')]].map(([h,p],i)=>`<article><span class="step-number">${i+1}</span><h3>${h}</h3><p class="card-sub">${p}</p></article>`).join('')}</div></section><section class="card card-pad guide-notes"><h2>${t('数据与计算说明','Data and calculation notes')}</h2><p>${t('默认使用 Palmer Penguins 真实科考数据，包含 344 条记录、8 个字段，CC0 授权。仅将原文件的 NA 解释为缺失值，没有补造观测。导入支持 CSV、TSV、JSON 和 Excel，每个文件最多 5 MB、20,000 行、80 列。','The default Palmer Penguins data contains 344 real observations and 8 fields, licensed CC0. Original NA markers become null; no observations are invented. Import CSV, TSV, JSON or Excel, up to 5 MB, 20,000 rows and 80 columns per file.')}</p><p>${t('每个数据集分别保留处理结果、操作记录、工作表搜索和图表设置。图表与分析始终使用当前数据集的完整记录，工作表搜索不影响图表。数据仅在当前页面会话中保存，刷新前请导出。','Each dataset retains its transformations, history, worksheet search and chart settings. Charts and analysis always use the complete working dataset; worksheet search does not affect charts. Data is retained for this page session only. Export before refreshing.')}</p><p>${t('处理操作先预览，点击应用后才修改数据，可撤销最近 20 步。前后对比使用相同坐标和分箱。数值统计忽略缺失，标准差为样本标准差，Pearson 使用成对有效值。疑似异常需人工判断；相关不代表因果。','Preview transformations before applying; the last 20 steps can be undone. Before/after comparisons share axes and bins. Numeric statistics omit missing values, use sample standard deviation and pairwise-valid Pearson correlation. Inspect potential outliers; correlation is not causation.')}</p><p>${t('参考 pandas 常用能力，以 JavaScript 在浏览器本地实现，并非 Python/pandas 运行环境。散点图超过 1,500 点时抽样显示；分组观测点最多每组 80 个；平行坐标最多 5 个字段、300 条线；散点矩阵最多 4 个字段、200 条抽样记录。统计使用全部有效记录，类别图展示数量限制会在图旁说明。','Common pandas capabilities are implemented in local JavaScript, not a Python/pandas runtime. Scatter displays sample above 1,500 points; grouped plots show up to 80 points per group; parallel coordinates show up to 5 fields and 300 lines; scatter matrices show up to 4 fields and 200 sampled rows. Statistics use all valid observations; category limits are explained beside the charts.')}</p><div class="reference-links"><a href="https://pandas.pydata.org/docs/" target="_blank" rel="noreferrer">pandas ↗</a><a href="https://allisonhorst.github.io/palmerpenguins/" target="_blank" rel="noreferrer">Palmer Penguins ↗</a></div></section>`;}
function acceptData(data,name,mode){if(mode==='join'){joinData=data;joinName=name;joinDatasetId='';pending=null;view='clean';render();}else setData(data,name,false);$('#modal').close();$('#fileInput').value='';importMode='replace';toast(t('已载入 ','Loaded ')+data.length+t(' 行。',' rows.'));}
document.addEventListener('click',e=>{const button=e.target.closest('[data-act]');if(!button||button.disabled)return;const a=button.dataset.act;
 const own=['applyPrepared','prepareMode','resetPrepareDraft','clearTableSearch','analysisRelation','inspectRecords','source','profile','applyMissing','dedupe','editColumn','calculate','previewJoin','confirmPreview','cancelPreview','history','aggregate','correlationPair','inspectRow','recommend','joinFile','readSheet'];
 if(a==='import'){importMode='replace';return;}if(['undo','confirmReset','sample'].includes(a)){pending=null;groupSpec=null;}if(a==='data')$('#modal').close();
 if(!own.includes(a))return;e.preventDefault();e.stopImmediatePropagation();try{
 if(a==='prepareMode'){clearTimeout(prepareUpdateTimer);prepareMode=button.dataset.mode;pending=null;render();}
 else if(a==='resetPrepareDraft'){clearTimeout(prepareUpdateTimer);prepareDrafts=P.reconcilePrepareDrafts(rows,cols,prepareDrafts);prepareDrafts[prepareMode]=P.defaultPrepareDrafts(rows,cols)[prepareMode];prepareResult=null;pending=null;renderPrepare();}
 else if(a==='clearTableSearch'){query='';page=0;render();}
 else if(a==='analysisRelation'){groupSpec={...(groupSpec||initialConfig(rows).groupSpec),relation:button.dataset.kind};render();}
 else if(a==='source'){modal(t('数据来源与字段说明','Source & field guide'),sourceDetails());}
 else if(a==='inspectRecords'){const list=current();modal(t('数据记录','Dataset records'),`<p class="card-sub">${t('共','Total')} ${fmt(list.length)} ${t('条，预览前 8 条；完整工作表位于“数据”。','rows. Preview of the first 8; the full worksheet is in Data.')}</p><div class="record-grid">${list.slice(0,8).map(r=>`<button class="record-chip" data-act="inspectRow" data-row="${rows.indexOf(r)}">#${rows.indexOf(r)+1}<span>${esc(val(r[cols[0]]))}</span>${icon('chevron')}</button>`).join('')||empty(t('没有匹配记录','No matching records'))}</div>`,btn('data',t('转到数据工作表','Open worksheet'),'table','primary'));}
 else if(a==='profile'){profileKey=button.dataset.key;render();}
 else if(a==='previewJoin')prepareAction(a);
 else if(a==='applyPrepared'&&pending?.kind==='prepare'){const p=pending;prepareResult=p.result;commit(p.next,p.zh,p.en,p.code,p.newcols);}
 else if(a==='confirmPreview'&&pending?.kind==='join'){const p=pending;prepareResult=p.kind==='prepare'?p.result:null;commit(p.next,p.zh,p.en,p.code,p.newcols);}
 else if(a==='cancelPreview'){pending=null;$('#cleanPreview').innerHTML='';renderPrepare(false);}
 else if(a==='history')modal(t('操作记录','Activity history'),historyView());
 else if(a==='aggregate'){const fn=get('groupAgg'),v=get('groupVal');if(fn!=='count'&&!colopts(true).some(([k])=>k===v))throw Error('NUMERIC');groupSpec={r:get('groupRow'),c:get('groupCol'),v,fn};renderAnalysisResult();}
 else if(a==='correlationPair'){chartX=button.dataset.x;chartY=button.dataset.y;chartType='scatter';view='charts';page=0;render();window.scrollTo(0,0);}
 else if(a==='inspectRow'){const r=rows[Number(button.dataset.row)];if(r)modal(t('原始记录详情','Source record details'),'<div class="table-scroll"><table><tbody>'+cols.map(k=>'<tr><th>'+esc(label(k))+'</th><td>'+esc(val(r[k]))+'</td></tr>').join('')+'</tbody></table></div>');}
 else if(a==='recommend'){const p=E.profile(rows,cols),x=p.find(c=>c.key===chartX),y=p.find(c=>c.key===chartY);chartType=x?.type==='date'?'line':x?.type==='number'&&y?.type==='number'?(chartX===chartY?'hist':'scatter'):'bar';render();toast(t('已根据字段类型推荐；可随时切换。','Suggested from field types; switch at any time.'));}
 else if(a==='joinFile'){importMode='join';$('#fileInput').click();}
 else if(a==='readSheet'){const w=workbook,table=XLSX.utils.sheet_to_json(w.book.Sheets[get('excelSheet')],{header:1,defval:null,raw:true});if(table.length<2)throw Error('EMPTY');const headers=table.shift().map(x=>String(x??'').trim());if(headers.some(x=>!x)||new Set(headers).size!==headers.length)throw Error('HEADERS');const data=E.validate(table.filter(r=>r.some(x=>!E.missing(x))).map(r=>Object.fromEntries(headers.map((k,i)=>[k,r[i] instanceof Date?r[i].toISOString().slice(0,10):r[i]??null]))));acceptData(data,w.name+' / '+get('excelSheet'),w.mode);}
 }catch(err){error(err);}
},true);
document.addEventListener('change',e=>{if(e.target.id==='datasetSelect'){switchDataset(e.target.value);return;}if(e.target.id==='joinDataset'){const id=e.target.value;joinDatasetId=id;if(id){const other=datasets.get(id);joinData=other.rows;joinName=other.dataset;}else{joinData=null;joinName='';}pending=null;render();return;}if(['chartType','chartX','chartY','chartAgg','chartColor'].includes(e.target.id)){chartType=get('chartType');chartX=get('chartX');chartY=get('chartY');chartAgg=get('chartAgg');chartColor=get('chartColor');render();}if(['timeKey','timeMetric','timeUnit'].includes(e.target.id)){timeKey=get('timeKey');timeMetric=get('timeMetric');timeUnit=get('timeUnit');render();}if(view==='clean'&&e.target.closest('.tool-card,.join-panel')){pending=null;$('#cleanPreview').innerHTML='';}});
document.addEventListener('input',e=>{if(view==='clean'&&e.target.closest('.tool-card,.join-panel')){pending=null;$('#cleanPreview').innerHTML='';}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [data-act]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
function sourceCard(missing){return '<div class="dataset-stats"><span><b>'+fmt(rows.length)+'</b> '+t('行','rows')+'</span><span><b>'+cols.length+'</b> '+t('列','columns')+'</span><span><b>'+missing+'</b> '+t('个缺失单元格','missing cells')+'</span><span><b>'+fmt(rows.length-E.dedupe(rows,cols).length)+'</b> '+t('条重复记录','duplicate rows')+'</span>'+btn('source',t('数据来源与字段','Source & fields'),'book','small ghost')+'</div>';}
function sourceDetails(){if(!isSample)return importedDetails();return `<p class="source-description">${t('数据由 Kristen Gorman 博士及 Palmer Station Antarctica LTER 采集，Palmer Penguins 项目整理发布。这里使用原始项目提供的简化版 penguins.csv，包含 2007—2009 年的 344 条真实观测。','Collected by Dr. Kristen Gorman and Palmer Station Antarctica LTER, and distributed by the Palmer Penguins project. This site uses their simplified penguins.csv: 344 real observations from 2007–2009.')}</p><div class="reference-links"><a href="https://allisonhorst.github.io/palmerpenguins/" target="_blank" rel="noreferrer">${t('项目与数据来源','Project & provenance')} ↗</a><a href="https://allisonhorst.github.io/palmerpenguins/reference/penguins.html" target="_blank" rel="noreferrer">${t('官方字段说明','Official field guide')} ↗</a><a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noreferrer">CC0 ↗</a><a href="./data/penguins.csv" download>${t('下载原始 CSV','Download original CSV')} ↓</a></div><p class="source-description">${t('原始文件完整保留。仅将其 NA 标记识别为缺失值；没有补造记录或测量值。物种名和字段名仅在显示时翻译，导出保留原始标识。','The original file is preserved. Only NA markers are interpreted as null; no records or measurements are generated. Display labels are translated; exports retain original identifiers.')}</p><div class="table-scroll"><table><tbody>${['species','island','bill_length_mm','bill_depth_mm','flipper_length_mm','body_mass_g','sex','year'].map(k=>`<tr><th>${k}</th><td>${t(...names[k])}</td></tr>`).join('')}</tbody></table></div><p class="card-sub">${t('获取日期：2026-10-15。校验信息见','Retrieved 2026-10-15. Checksum and provenance:')} <a href="./data/source.json" target="_blank">source.json ↗</a></p>`;}
function datasetSize(){return '<span class="dataset-size">'+icon('rows')+fmt(rows.length)+' '+t('行','rows')+'</span>';}
function fieldEmpty(state,key){const isEmpty=!rows.length;return `<div class="selection-empty"><strong>${isEmpty?t('当前工作数据没有记录','The working dataset has no rows'):t('该字段没有有效数值','This field has no valid numbers')}</strong><p>${isEmpty?t('请恢复原始数据，或添加另一个数据集。','Restore the original data or add another dataset.'):t('请选择其他数值字段，或在“处理”中检查缺失值与字段类型。','Choose another numeric field or inspect missing values and field types in Prepare.')}</p>${isEmpty?btn('reset',t('恢复原始数据','Restore original'),'reset','small'):''}</div>`;}
function tableEmpty(){return rows.length?'<div class="selection-empty"><strong>'+t('工作表中未找到该关键词','No worksheet rows contain this keyword')+'</strong><p>'+t('搜索只影响工作表，图表与分析仍使用完整数据。','Search only affects the worksheet. Charts and analysis still use the full dataset.')+'</p>'+btn('clearTableSearch',t('清空搜索','Clear search'),'close','small')+'</div>':fieldEmpty(null,cols[0]);}

function categoryFields(){return E.profile(rows,cols).filter(c=>c.type!=='date'&&c.unique<=30).sort((a,b)=>Number(a.type==='number')-Number(b.type==='number')).map(c=>[c.key,label(c.key)]);}
function captureDataset(){return {rows,original,cols,dataset,isSample,history,undo,page,query,sort,visible,chartType,chartX,chartY,chartAgg,analysisResult,profileKey,groupSpec,timeKey,timeMetric,timeUnit,chartColor,joinData,joinName,joinDatasetId,prepareMode,prepareDrafts,prepareResult};}
function switchDataset(id){if(id===activeDataset)return;datasets.save(activeDataset,captureDataset());const state=datasets.get(id);({rows,original,cols,dataset,isSample,history,undo,page,query,sort,visible,chartType,chartX,chartY,chartAgg,analysisResult,profileKey,groupSpec,timeKey,timeMetric,timeUnit,chartColor,joinData,joinName,joinDatasetId,prepareMode,prepareDrafts,prepareResult}=state);activeDataset=id;pending=null;workbook=null;$('#modal').close();render();}
function datasetPicker(){return `<div class="dataset-picker"><label for="datasetSelect">${t('数据集','Dataset')} <span>${datasets.list().length}</span></label><select id="datasetSelect" title="${esc(dataset)}">${datasets.list().map(d=>opt(d.id,d.name+' · '+(d.id===activeDataset?rows.length:d.rows)+' '+t('行','rows'),d.id===activeDataset?d.id:null)).join('')}</select><small>${t('当前页面会话 · 切换保留处理结果','This page session · Switching preserves changes')}</small></div>`;}
function datasetJoinPicker(){const other=datasets.list().filter(d=>d.id!==activeDataset);return other.length?'<div class="form-row">'+field(t('使用已载入的数据集','Use a loaded dataset'),select('joinDataset',[['',t('选择数据集','Choose dataset')],...other.map(d=>[d.id,d.name+' · '+d.rows+' '+t('行','rows')])],joinDatasetId))+'</div>':'';}
function importedDetails(){return `<p class="source-description">${t('来源：本地导入文件','Source: locally imported file')} <strong>${esc(dataset)}</strong>。${t('原始导入','Original import')}: ${original.length} ${t('行','rows')} × ${E.columns(original).length} ${t('列','columns')}。</p><div class="table-scroll"><table><thead><tr><th>${t('字段','Field')}</th><th>${t('类型','Type')}</th><th>${t('缺失','Missing')}</th></tr></thead><tbody>${E.profile(rows,cols).map(c=>`<tr><th>${esc(c.key)}</th><td>${c.type==='number'?t('数值','Number'):c.type==='date'?t('日期','Date'):t('文本','Text')}</td><td>${c.missing}</td></tr>`).join('')}</tbody></table></div>`;}

const extras=createVisuals({t,esc,label,val,fmt,short,shortLabel,color,getRows:()=>rows});
const prepareVisuals=createPrepareVisuals({t,esc,label,val,fmt,short,extras});
const initial=initialConfig(rows);({chartType,chartX,chartY,chartAgg,chartColor,profileKey,groupSpec,timeKey,timeMetric,timeUnit}=initial);
activeDataset=datasets.add(captureDataset());
render();
